insert into public.product_chapters (product_id, locale, position, title, body_html, minutes, is_sample) select id, 'en', 1, 'Whose money is it?', '<p>Before we talk about budgets, we need to settle a bigger question: whose money is it? Scripture answers plainly. Everything we have is on loan from God, and we are stewards, not owners.</p><p>That changes how we earn, how we spend and how we give. A steward asks, “What would the Owner want me to do with this?” The rest of this book is about answering that question in everyday life.</p>', 12, true from public.products where slug = 'money';
