insert into public.product_chapters (product_id, locale, position, title, body_html, minutes, is_sample) select id, 'pt', 1, 'De quem é o dinheiro?', '<p>Antes de falarmos de orçamentos, precisamos de responder a uma pergunta maior: de quem é o dinheiro? A Escritura responde com clareza. Tudo o que temos é emprestado por Deus; somos mordomos, não donos.</p><p>Isso muda a forma como ganhamos, gastamos e damos. Um mordomo pergunta: “O que é que o Dono quer que eu faça com isto?” O resto deste livro ajuda a responder a essa pergunta no dia a dia.</p>', 12, true from public.products where slug = 'money';
