insert into public.product_chapters (product_id, locale, position, title, body_html, minutes, is_sample) select id, 'es', 1, '¿De quién es el dinero?', '<p>Antes de hablar de presupuestos, debemos responder una pregunta mayor: ¿de quién es el dinero? La Escritura responde con claridad. Todo lo que tenemos es prestado por Dios; somos mayordomos, no dueños.</p><p>Eso cambia cómo ganamos, gastamos y damos. Un mayordomo pregunta: «¿Qué quiere el Dueño que haga con esto?». El resto de este libro ayuda a responder esa pregunta en el día a día.</p>', 12, true from public.products where slug = 'money';
