insert into public.product_chapters (product_id, locale, position, title, body_html, minutes, is_sample) select id, 'en', 1, 'Pray and choose the passage', '<p>Every good sermon starts on your knees, not at your desk. Before you open a commentary, ask God what He wants His people to hear this Sunday.</p><p>Then choose one passage and stay with it. A clear text, read slowly and prayerfully, will give you more than ten passages skimmed in a hurry.</p>', 8, true from public.products where slug = 'sermon';
