insert into public.product_chapters (product_id, locale, position, title, body_html, minutes, is_sample) select id, 'en', 1, 'The preacher’s calling', '<p>Use this page to write down why you preach. Be honest: who called you, where, and what did you sense God asking of you?</p><p>Come back to this page before every sermon you plan in this workbook. Your calling is the anchor that keeps your preaching steady.</p>', 10, true from public.products where slug = 'workbook';
